    ctypes.POINTER(ctypes.c_double),
    ctypes.POINTER(ctypes.c_size_t)
]

def integrate_function(func, a, b, epsabs, epsrel, workspace_size):
    try:
        gsl.gsl_integration_cquad.restype = ctypes.c_int
        gsl_function = GSLFunction()
        gsl_function.f = ctypes.CFUNCTYPE(ctypes.c_double, ctypes.c_double)(func)
        workspace = CQuadWorkspace()
        result = gsl.gsl_integration_cquad(
            ctypes.byref(gsl_function),
            a, b, epsabs, epsrel, workspace_size,
            ctypes.byref(workspace),
            ctypes.pointer(ctypes.c_double()),
            ctypes.pointer(ctypes.c_double()),
            ctypes.pointer(ctypes.c_size_t())
        )
        if result != 0:
            raise RuntimeError("Integration failed with code {}".format(result))
        return {
            "Candidate_solution": json.dumps({
                "integral": workspace.result,
                "abs_error": workspace.abserror,
                "evaluations": workspace.neval
            })
        }
    except Exception as e:
        return {"Candidate_solution": json.dumps({"error": str(e)})}

