# Define GSLMatrix class
class GSLMatrix(ctypes.Structure):
    _fields_ = [("rows", ctypes.c_int), ("cols", ctypes.c_int), ("data", ctypes.POINTER(ctypes.c_double))]

# Define functions
def gsl_matrix_alloc(rows, cols):
    return GSLMatrix(rows, cols, (ctypes.c_double * (rows * cols))())

def gsl_matrix_free(matrix):
    gsl.gsl_matrix_free(matrix)

def numpy_to_gsl_matrix(np_array):
    return gsl_matrix_alloc(np_array.shape[0], np_array.shape[1])

def gsl_matrix_to_numpy(gsl_matrix):
    return np.ctypeslib.as_array(gsl_matrix.data, shape=(gsl_matrix.rows, gsl_matrix.cols))

def gsl_multifit_covar(jacobian, epsrel):
    return gsl_matrix_to_numpy(gsl.gsl_multifit_covar(jacobian, epsrel))

# Define the program
def covariance_matrix(jacobian, epsrel, dim):
    if dim != jacobian.shape[0] or dim != jacobian.shape[1]:
        raise ValueError("Invalid dimensions.")

    gsl_jacobian = numpy_to_gsl_matrix(jacobian)
    covariance_matrix = gsl_multifit_covar(gsl_jacobian, epsrel)
    gsl_matrix_free(gsl_jacobian)

    return covariance_matrix.tolist()

