def cholesky_decomp(matrix):
    # Create a GSL matrix
    rows, cols = len(matrix), len(matrix[0])
    gsl_matrix = GSLMatrix()
    gsl.gsl_matrix_init(&gsl_matrix, rows, cols)

    # Set the matrix elements
    for i in range(rows):
        for j in range(cols):
            gsl.gsl_matrix_set(&gsl_matrix, i, j, matrix[i][j])

    # Perform Cholesky decomposition
    status = gsl.gsl_linalg_cholesky_decomp(&gsl_matrix)

    # Check for errors
    if status != 0:
        raise ValueError("Cholesky decomposition failed.")

    # Extract the lower triangular matrix
    lower_matrix = [[gsl.gsl_matrix_get(&gsl_matrix, i, j) for j in range(i + 1)] for i in range(rows)]

    # Free the GSL matrix
    gsl.gsl_matrix_free(&gsl_matrix)

    return lower_matrix

def decompose_matrix(matrix):
    if not is_positive_definite(matrix):
        raise ValueError("Matrix is not positive definite.")

    try:
        lower_matrix = cholesky_decomp(matrix)
        return json.dumps({"Candidate_solution": str(lower_matrix)})
    except Exception as e:
        return json.dumps({"Candidate_solution": str(e)})

