# Define the GSL_Histogram2D class
class GSL_Histogram2D(ctypes.Structure):
    pass

# Define the create_histogram2d function
def create_histogram2d(nx, ny, xrange, yrange):
    # Validate input
    if not isinstance(nx, int) or not isinstance(ny, int):
        raise ValueError("nx and ny must be integers")
    if not isinstance(xrange, list) or not isinstance(yrange, list):
        raise ValueError("xrange and yrange must be lists")
    if len(xrange) != nx + 1 or len(yrange) != ny + 1:
        raise ValueError("Invalid xrange and yrange dimensions")
    if not all(xrange[i] < xrange[i+1] for i in range(nx)):
        raise ValueError("xrange must be in increasing order")
    if not all(yrange[i] < yrange[i+1] for i in range(ny)):
        raise ValueError("yrange must be in increasing order")

    # Create the gsl_histogram2d structure
    histogram = gsl.gsl_histogram2d_calloc_range(nx, ny, xrange, yrange)

    # Check for errors
    if not histogram:
        raise RuntimeError("Error creating histogram")

    # Return a pointer to the gsl_histogram2d structure
    return ctypes.pointer(histogram)

