import ctypes
import json

class Histogram:
    def __init__(self):
        self.bins = []

    def add_bin(self, lower_bound, upper_bound, count):
        self.bins.append((lower_bound, upper_bound, count))

    def to_json(self):
        return json.dumps({"Candidate_solution": self.to_string()})

    def to_string(self):
        return '\n'.join([f"{lower_bound} {upper_bound} {count}" for lower_bound, upper_bound, count in self.bins])

def compute_histogram(data, xmin, xmax):
    ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
    gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

    n_bins = int(xmax - xmin)
    histogram = Histogram()

    gsl.gsl_histogram_init(n_bins)

    for value in data:
        gsl.gsl_histogram_increment(value)

    for i in range(n_bins):
        lower_bound = xmin + i * (xmax - xmin) / n_bins
        upper_bound = xmin + (i + 1) * (xmax - xmin) / n_bins
        count = gsl.gsl_histogram_get_value(i)
        histogram.add_bin(lower_bound, upper_bound, count)

    gsl.gsl_histogram_free()

    return histogram.to_json()

